pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address caller, bytes32 guess) public {
        vm.assume(caller != address(0));

        vm.deal(caller, 2 ether);

        uint256 before = block.number;

        vm.prank(caller);
        bool ok;
        (bool success, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", guess));
        ok = success;

        if (!ok) {
            return;
        }

        vm.roll(block.number + 1);

        vm.prank(caller);
        (bool settleSuccess, ) = address(c).call(abi.encodeWithSignature("settle()"));

        assertTrue(!settleSuccess);
    }
}
